INSERT INTO `product` (`id`, `name`, `subtitle`, `description`, `category`, `price`, `stock`, `sales`, `main_image`, `status`, `created_at`) VALUES
(1,  '降噪蓝牙耳机 Pro',       '主动降噪，40 小时长续航', '支持 ANC 主动降噪与通透模式，单次续航 8 小时，配合充电盒 40 小时。\n蓝牙 5.3 低延迟连接，支持双设备切换。', '数码', 499.00, 120, 356,  NULL, 1, '2026-10-01 10:00:00'),
(2,  '机械键盘 K87',           '热插拔轴体，RGB 背光',    '87 键紧凑布局，支持热插拔更换轴体。\nPBT 双色键帽，有线 / 蓝牙 / 2.4G 三模连接。',                        '数码', 299.00, 0,   210,  NULL, 1, '2026-10-01 10:05:00'),
(3,  '智能手表 S3',            '血氧心率监测，14 天续航', '1.43 英寸 AMOLED 屏幕，支持全天候心率、血氧、睡眠监测。\n100+ 运动模式，5ATM 防水。',                     '数码', 899.00, 45,  128,  NULL, 1, '2026-10-02 11:00:00'),
(4,  '65W 氮化镓充电器',       '三口快充，小巧便携',      '2C1A 三口输出，单口最高 65W，可为笔记本、手机、平板快充。\n折叠插脚，出差旅行好伴侣。',                   '数码', 129.00, 300, 642,  NULL, 1, '2026-10-02 11:30:00'),
(5,  '纯棉圆领 T 恤',          '新疆长绒棉，亲肤透气',    '精选新疆长绒棉，220g 重磅面料，不易变形。\n多色可选，四季百搭。',                                         '服饰', 79.00,  500, 1205, NULL, 1, '2026-10-03 09:00:00'),
(6,  '轻薄羽绒服',             '90% 白鸭绒，可收纳',      '90% 白鸭绒填充，蓬松保暖，整衣可收纳进随附收纳袋。\n防泼水面料，适合秋冬通勤。',                         '服饰', 459.00, 80,  233,  NULL, 1, '2026-10-03 09:30:00'),
(7,  '休闲运动鞋',             '缓震回弹，轻量透气',      '一体织鞋面透气不闷脚，EVA 中底缓震回弹。\n单只约 260g，日常通勤、慢跑皆宜。',                             '服饰', 329.00, 150, 418,  NULL, 1, '2026-10-04 14:00:00'),
(8,  '316 不锈钢保温杯 500ml', '12 小时长效保温',         '316 医用级不锈钢内胆，真空隔热，保温保冷 12 小时。\n一键弹盖，单手可开。',                                 '家居', 129.00, 260, 876,  NULL, 1, '2026-10-05 10:00:00'),
(9,  '记忆棉护颈枕',           '慢回弹，贴合颈椎',        '高密度慢回弹记忆棉，波浪曲线贴合颈椎。\n可拆洗枕套，透气抑菌。',                                         '家居', 159.00, 90,  301,  NULL, 1, '2026-10-06 16:00:00'),
(10, '香薰加湿器',             '静音运行，七彩夜灯',      '超声波雾化，运行噪音低于 30dB。\n支持精油香薰，七彩夜灯可调。',                                           '家居', 189.00, 30,  57,   NULL, 0, '2026-10-06 16:30:00'),
(11, '云南小粒咖啡豆 500g',    '中度烘焙，坚果风味',      '云南保山小粒咖啡，中度烘焙，坚果与焦糖风味。\n下单后新鲜烘焙，适合手冲与意式。',                         '食品', 68.00,  400, 932,  NULL, 1, '2026-10-07 08:00:00'),
(12, '每日坚果 30 袋装',       '6 种坚果果干科学配比',    '腰果、巴旦木、榛子、核桃仁、蔓越莓干、蓝莓干科学配比。\n独立小袋包装，每日一袋。',                       '食品', 99.00,  350, 1580, NULL, 1, '2026-10-07 08:30:00'),
(13, '氨基酸洁面乳',           '温和清洁，敏感肌可用',    '氨基酸表活，弱酸性配方，洗后不紧绷。\n无香精、无酒精，敏感肌可用。',                                     '美妆', 89.00,  220, 764,  NULL, 1, '2026-10-08 13:00:00'),
(14, '保湿修护面霜',           '神经酰胺修护屏障',        '添加神经酰胺与角鲨烷，修护肌肤屏障，长效保湿。\n质地轻盈好吸收。',                                       '美妆', 199.00, 110, 389,  NULL, 1, '2026-10-08 13:30:00'),
(15, '《深入理解计算机系统》', '程序员必读经典',          '从程序员视角讲解计算机系统的本质概念。\n涵盖数据表示、汇编、处理器、存储、链接、异常控制流、虚拟内存、网络与并发。', '图书', 139.00, 60,  215,  NULL, 1, '2026-10-09 10:00:00'),
(16, '《人工智能：现代方法》', 'AI 领域经典教材',         '全面介绍人工智能的理论与实践。\n涵盖搜索、知识表示、规划、机器学习、自然语言处理与机器人等主题。',         '图书', 168.00, 40,  97,   NULL, 1, '2026-10-09 10:30:00');
